"use client";

import { useState } from "react";
import type { BoardDto, PostId } from "afferent";
import {
  useAdminCapability,
  useAdminFeedback,
  useAdminPost,
  usePostActivity,
} from "afferent/react.js";
import { AfferentChangelogEditor } from "@/components/afferent/admin/changelog-editor";
import { AfferentFeedbackQueue } from "@/components/afferent/admin/feedback-queue";
import { AfferentMergeDialog } from "@/components/afferent/admin/merge-dialog";
import { AfferentModerationForm } from "@/components/afferent/admin/moderation-form";
import { AfferentTagManager } from "@/components/afferent/admin/tag-manager";
import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import {
  AfferentStateRegion,
  assertNever,
} from "@/components/afferent/core/state-region";

export function AfferentAdminScreen({
  boards = [],
  pageOwner = true,
}: Readonly<{ boards?: readonly BoardDto[]; pageOwner?: boolean }>) {
  const { copy } = useAfferentUi();
  const capability = useAdminCapability();
  const visible = useAdminFeedback("visible");
  const hidden = useAdminFeedback("hidden");
  const [selected, setSelected] = useState<PostId | undefined>();
  const body = (
    <div className="afferent-admin" data-afferent-screen="admin">
      <header>
        <h1>{copy.admin.title}</h1>
      </header>
      {render()}
    </div>
  );
  function render() {
    switch (capability.status) {
      case "unsupported": {
        return (
          <AfferentStateRegion title={copy.common.unsupportedHeading}>
            <p>{copy.common.unsupportedBody}</p>
          </AfferentStateRegion>
        );
      }
      case "loading": {
        return <AfferentStateRegion title={copy.common.loading} />;
      }
      case "not-authorized": {
        return (
          <AfferentStateRegion title={copy.common.notAuthorizedHeading}>
            <p>{copy.common.notAuthorizedBody}</p>
          </AfferentStateRegion>
        );
      }
      case "error": {
        return (
          <AfferentStateRegion title={copy.admin.loadError} tone="error" />
        );
      }
      case "ready": {
        return (
          <div className="afferent-admin-workspace" data-admin-workspace>
            <AfferentFeedbackQueue
              feed={visible}
              selectedId={selected}
              onSelect={setSelected}
            />
            <AdminDetail
              postId={selected}
              boards={boards}
              candidates={[...visible.items, ...hidden.items]}
            />
            <AfferentChangelogEditor
              feedback={[...visible.items, ...hidden.items]}
            />
          </div>
        );
      }
      default: {
        return assertNever(capability);
      }
    }
  }
  return pageOwner ? <main>{body}</main> : body;
}
function AdminDetail({
  postId,
  boards,
  candidates,
}: Readonly<{
  postId?: PostId;
  boards: readonly BoardDto[];
  candidates: readonly any[];
}>) {
  if (!postId)
    return (
      <section>
        <h2>Select feedback</h2>
      </section>
    );
  return (
    <AdminPostDetail postId={postId} boards={boards} candidates={candidates} />
  );
}
function AdminPostDetail({
  postId,
  boards,
  candidates,
}: Readonly<{
  postId: PostId;
  boards: readonly BoardDto[];
  candidates: readonly any[];
}>) {
  const state = useAdminPost(postId);
  const activity = usePostActivity(postId);
  if (state.status !== "ready") return <p role="status">{state.status}</p>;
  return (
    <section className="afferent-admin-detail">
      <AfferentModerationForm post={state.post} boards={boards} />
      <AfferentTagManager post={state.post} />
      <section>
        <h2>Activity</h2>
        <ol>
          {activity.items.map((item) => (
            <li key={item.id}>{item.type.replaceAll("_", " ")}</li>
          ))}
        </ol>
      </section>
      <AfferentMergeDialog source={state.post} candidates={candidates} />
    </section>
  );
}

"use client";

import { useState, type FormEvent } from "react";
import type { AdminChangelogEntryDto, AdminFeedbackPostDto } from "afferent";
import { useAdminChangelog, useChangelogEditor } from "afferent/react.js";
import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";

export function AfferentChangelogEditor({
  feedback,
}: Readonly<{ feedback: readonly AdminFeedbackPostDto[] }>) {
  const { copy } = useAfferentUi();
  const entries = useAdminChangelog();
  const editor = useChangelogEditor();
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  function create(event: FormEvent) {
    event.preventDefault();
    void editor.createDraft({ title, body });
  }
  return (
    <section className="afferent-changelog-editor">
      <h2>{copy.admin.changelogHeading}</h2>
      <form onSubmit={create}>
        <label>
          Changelog title
          <input
            value={title}
            onChange={(event) => setTitle(event.currentTarget.value)}
          />
        </label>
        <label>
          Changelog body
          <textarea
            value={body}
            onChange={(event) => setBody(event.currentTarget.value)}
          />
        </label>
        <button type="submit">{copy.admin.saveChangelogDraft}</button>
      </form>
      {entries.status === "ready" ? (
        <ol>
          {entries.items.map((entry) => (
            <Entry key={entry.id} entry={entry} feedback={feedback} />
          ))}
        </ol>
      ) : (
        <p role="status">{entries.status}</p>
      )}
    </section>
  );
  function Entry({
    entry,
    feedback,
  }: Readonly<{
    entry: AdminChangelogEntryDto;
    feedback: readonly AdminFeedbackPostDto[];
  }>) {
    return (
      <li>
        <article>
          <h3>{entry.title}</h3>
          <p>{entry.state}</p>
          <fieldset>
            <legend>Linked feedback</legend>
            {feedback.map((post) => (
              <label key={post.feedback.id}>
                <input
                  type="checkbox"
                  defaultChecked={entry.links.some(
                    (link) => link.id === post.feedback.id,
                  )}
                  onChange={() =>
                    void editor.setLinks({
                      entryId: entry.id,
                      postIds: [post.feedback.id],
                    })
                  }
                />
                {post.feedback.title}
              </label>
            ))}
          </fieldset>
          <button
            type="button"
            onClick={() =>
              void (entry.state === "published"
                ? editor.unpublish(entry.id)
                : editor.publish(entry.id))
            }
          >
            {entry.state === "published"
              ? copy.admin.unpublishChangelog
              : copy.admin.publishChangelog}
          </button>
        </article>
      </li>
    );
  }
}

import type { AdminFeedbackState } from "afferent/react.js";

import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import {
  AfferentStateRegion,
  assertNever,
} from "@/components/afferent/core/state-region";

export function AfferentFeedbackQueue({
  feed,
  selectedId,
  onSelect,
}: Readonly<{
  feed: AdminFeedbackState;
  selectedId?: string;
  onSelect: (id: any) => void;
}>) {
  const { copy } = useAfferentUi();
  switch (feed.status) {
    case "unsupported": {
      return <AfferentStateRegion title={copy.common.unsupportedHeading} />;
    }
    case "loading": {
      return <AfferentStateRegion title={copy.common.loading} />;
    }
    case "not-authorized": {
      return <AfferentStateRegion title={copy.common.notAuthorizedHeading} />;
    }
    case "empty": {
      return (
        <AfferentStateRegion title={copy.admin.emptyHeading}>
          <p>{copy.admin.emptyBody}</p>
        </AfferentStateRegion>
      );
    }
    case "error": {
      return <AfferentStateRegion title={copy.admin.loadError} tone="error" />;
    }
    case "loading-more":
    case "ready": {
      return (
        <section aria-label={copy.admin.queueHeading}>
          <h2>{copy.admin.queueHeading}</h2>
          <ol className="afferent-admin-queue">
            {feed.items.map((item) => (
              <li
                key={item.feedback.id}
                data-admin-feedback
                data-selected={selectedId === item.feedback.id}
              >
                <button
                  type="button"
                  onClick={() => onSelect(item.feedback.id)}
                >
                  <span data-admin-label="Feedback">{item.feedback.title}</span>
                  <span data-admin-label="Status">
                    {item.feedback.status.label}
                  </span>
                  <span data-admin-label="Board">
                    {item.feedback.board.name}
                  </span>
                </button>
              </li>
            ))}
          </ol>
          {feed.canLoadMore ? (
            <button
              type="button"
              className="afferent-button afferent-button--secondary"
              onClick={feed.loadMore}
            >
              {copy.admin.loadMore}
            </button>
          ) : null}
        </section>
      );
    }
    default: {
      return assertNever(feed.status as never);
    }
  }
}

"use client";

import { useRef, useState } from "react";
import type { AdminFeedbackPostDto, PostId } from "afferent";
import { Dialog } from "radix-ui";
import { moderationActionKey, useMergePost } from "afferent/react.js";
import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";

export function AfferentMergeDialog({
  source,
  candidates,
}: Readonly<{
  source: AdminFeedbackPostDto;
  candidates: readonly AdminFeedbackPostDto[];
}>) {
  const { copy } = useAfferentUi();
  const merge = useMergePost();
  const [typed, setTyped] = useState("");
  const [target, setTarget] = useState<PostId | "">(
    candidates[0]?.feedback.id ?? "",
  );
  const trigger = useRef<HTMLButtonElement>(null);
  const key = moderationActionKey(source.feedback.id, "merge");
  return (
    <Dialog.Root>
      <Dialog.Trigger asChild>
        <button ref={trigger} type="button">
          {copy.admin.mergeDuplicate}
        </button>
      </Dialog.Trigger>
      <Dialog.Portal>
        <Dialog.Overlay className="afferent-dialog-overlay" />
        <Dialog.Content
          className="afferent-dialog"
          onCloseAutoFocus={(event) => {
            event.preventDefault();
            trigger.current?.focus();
          }}
        >
          <Dialog.Title>{copy.admin.mergeDuplicate}</Dialog.Title>
          <Dialog.Description>
            Type “{source.feedback.title}” to confirm this irreversible merge.
          </Dialog.Description>
          <label>
            Canonical feedback
            <select
              value={target}
              onChange={(event) =>
                setTarget(event.currentTarget.value as PostId | "")
              }
            >
              {candidates
                .filter((item) => item.feedback.id !== source.feedback.id)
                .map((item) => (
                  <option key={item.feedback.id} value={item.feedback.id}>
                    {item.feedback.title}
                  </option>
                ))}
            </select>
          </label>
          <label>
            Duplicate title
            <input
              value={typed}
              onChange={(event) => setTyped(event.currentTarget.value)}
            />
          </label>
          <button
            type="button"
            disabled={
              typed !== source.feedback.title || !target || merge.pending[key]
            }
            onClick={() =>
              void merge.merge({
                sourcePostId: source.feedback.id,
                canonicalPostId: target as PostId,
              })
            }
          >
            {copy.admin.mergeDuplicate}
          </button>
          <Dialog.Close asChild>
            <button type="button">{copy.detail.keepFeedback}</button>
          </Dialog.Close>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

"use client";

import { useState, type FormEvent } from "react";
import type { AdminFeedbackPostDto, BoardDto, PostStatusKey } from "afferent";
import { moderationActionKey, usePostModeration } from "afferent/react.js";

import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";

const statuses: readonly PostStatusKey[] = [
  "open",
  "under_review",
  "planned",
  "in_progress",
  "complete",
  "closed",
];

export function AfferentModerationForm({
  post,
  boards,
}: Readonly<{ post: AdminFeedbackPostDto; boards: readonly BoardDto[] }>) {
  const { copy } = useAfferentUi();
  const moderation = usePostModeration();
  const [title, setTitle] = useState(post.feedback.title);
  const [body, setBody] = useState(post.feedback.body);
  const id = post.feedback.id;
  const run = (action: string, invoke: () => unknown) => (
    <button
      type="button"
      disabled={moderation.pending[moderationActionKey(id, action as any)]}
      onClick={() => void invoke()}
    >
      {action}
    </button>
  );
  function save(event: FormEvent) {
    event.preventDefault();
    void moderation.editPost({ postId: id, title, body });
  }
  return (
    <form
      className="afferent-admin-form"
      onSubmit={save}
      aria-label={copy.admin.moderationHeading}
    >
      <h2>{copy.admin.moderationHeading}</h2>
      <label>
        Feedback title
        <input
          value={title}
          onChange={(event) => setTitle(event.currentTarget.value)}
        />
      </label>
      <label>
        Feedback details
        <textarea
          value={body}
          onChange={(event) => setBody(event.currentTarget.value)}
        />
      </label>
      <button className="afferent-button" type="submit">
        {copy.admin.saveModeration}
      </button>
      <label>
        Board
        <select
          name="board"
          defaultValue={post.feedback.boardId}
          onChange={(event) =>
            void moderation.movePost({
              postId: id,
              boardId: event.currentTarget.value as any,
            })
          }
        >
          {boards.map((candidate) => (
            <option key={candidate.id} value={candidate.id}>
              {candidate.name}
            </option>
          ))}
        </select>
      </label>
      <label>
        {copy.admin.updateStatus}
        <select
          name="status"
          defaultValue={post.feedback.status.key}
          onChange={(event) =>
            void moderation.setPostStatus({
              postId: id,
              status: event.currentTarget.value as PostStatusKey,
            })
          }
        >
          {statuses.map((status) => (
            <option key={status} value={status}>
              {status.replaceAll("_", " ")}
            </option>
          ))}
        </select>
      </label>
      <div className="afferent-actions">
        {run(
          post.moderation.discussionLocked
            ? "Unlock discussion"
            : "Lock discussion",
          () =>
            moderation.setDiscussionLock({
              postId: id,
              locked: !post.moderation.discussionLocked,
            }),
        )}
        {run(
          post.moderation.archived
            ? copy.admin.restoreFeedback
            : copy.admin.archiveFeedback,
          () =>
            moderation.setArchived({
              postId: id,
              archived: !post.moderation.archived,
            }),
        )}
      </div>
    </form>
  );
}

"use client";

import { useState, type FormEvent } from "react";
import type { AdminFeedbackPostDto } from "afferent";
import { useTagManagement, useTags } from "afferent/react.js";
import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";

export function AfferentTagManager({
  post,
}: Readonly<{ post: AdminFeedbackPostDto }>) {
  const { copy } = useAfferentUi();
  const tags = useTags();
  const management = useTagManagement();
  const [name, setName] = useState("");
  function create(event: FormEvent) {
    event.preventDefault();
    if (name.trim()) void management.createTag({ name: name.trim() });
  }
  return (
    <section>
      <h2>{copy.admin.manageTags}</h2>
      <form onSubmit={create}>
        <label>
          New tag
          <input
            value={name}
            onChange={(event) => setName(event.currentTarget.value)}
          />
        </label>
        <button type="submit">Create tag</button>
      </form>
      {tags.status === "ready" ? (
        <ul>
          {tags.items.map((tag) => {
            const assigned = post.feedback.tags.some(
              (item) => item.id === tag.id,
            );
            return (
              <li key={tag.id}>
                <span>{tag.name}</span>
                <button
                  type="button"
                  onClick={() =>
                    void management.setPostTag({
                      postId: post.feedback.id,
                      tagId: tag.id,
                      desired: !assigned,
                    })
                  }
                >
                  {assigned ? "Remove tag" : "Assign tag"}
                </button>
                <button
                  type="button"
                  onClick={() => void management.deleteTag({ tagId: tag.id })}
                >
                  Delete tag
                </button>
              </li>
            );
          })}
        </ul>
      ) : (
        <p role="status">{tags.status}</p>
      )}
    </section>
  );
}
